// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(this));

        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;

        vm.prank(caller);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("withdrawAll(address)", recipient));
        uint256 balanceAfter = address(c).balance;

        assertTrue(!success || balanceAfter == balanceBefore);
    }
}
